def countEven(num):
    # Helper function to find the digit sum of a number
    def digit_sum(x):
        s = 0
        while x > 0:
            s += x % 10
            x //= 10
        return s

    count = 0
    # Iterate from 1 to num (inclusive)
    for val in range(1, num + 1):
        if digit_sum(val) % 2 == 0:
            count += 1
    return count
